      if(!_madBsVacia(ps) && _madBsNum(ps.v)==="") avisos.push("La piscina "+madBsNormPiscina(p.piscina)+" trae en «Peso de siembra» «"+_madBsTexto(ps)+"», que no es un peso ni unas Pl/g: se sube vacío.");
